// venda aprovada que ainda nao foi marcada na coluna conversao_google
const vis = {}; for (const i of $('Ler Visitantes').all()) { const v = i.json; if (v && v.id_netliss) vis[String(v.id_netliss)] = v; }
const num = s => { s = String(s || '').replace('R$', '').trim(); if (!s) return 0; const t = s.includes(',') ? s.split('.').join('').replace(',', '.') : s; const n = Number(t); return isNaN(n) ? 0 : n; };
const quando = s => { const m = String(s || '').match(/(\d{2})\/(\d{2})\/(\d{4}),?\s+(\d{2}):(\d{2})/); return m ? m[3] + '-' + m[2] + '-' + m[1] + ' ' + m[4] + ':' + m[5] + ':00-0300' : ''; };
const enviar = [], semGclid = [], semValor = [];
for (const i of $('Ler Pagamentos').all()) {
  const p = i.json; if (!p || !p.row_number || !String(p.payment_id || '').trim()) continue;
  if (String(p.status_pagamento || '').trim() !== 'approved' || String(p.conversao_google || '').trim() !== '') continue;
  const v = vis[String(p.id_netliss)] || {};
  const gclid = String(p.gclid || v.gclid || '').trim(); const valor = num(p.valor || v.valor);
  if (gclid.length <= 5) { semGclid.push({ row_number: p.row_number, conversao_google: 'sem_gclid' }); continue; }
  if (!(valor > 0)) { semValor.push('ATENCAO: VENDA DO GOOGLE ADS SEM VALOR\n\nPagamento ' + p.payment_id + ' (linha ' + p.row_number + ' da aba Pagamentos) tem GCLID, mas o valor esta vazio ou invalido: "' + (p.valor || '') + '".\n\nEla NAO foi enviada ao Google Ads. Preencha a coluna F (valor) dessa linha: na proxima noite, as 23:50, ela e enviada automaticamente.'); continue; }
  const t = quando(p.data_aprovacao) || quando(p.data_criacao); if (!t) continue;
  enviar.push({ conv: { 'Google Click ID': gclid, 'Conversion Name': 'Venda Netliss', 'Conversion Time': t, 'Conversion Value': valor.toFixed(2), 'Conversion Currency': 'BRL', 'Ad User Data': 'GRANTED', 'Ad Personalization': 'GRANTED' },
    marca: { row_number: p.row_number, gclid, conversao_google: 'enviada' } });
}
return [{ json: { enviar, semGclid, semValor } }];
